// Extrae y estandariza mensajes de WhatsApp y Telegram
// para que un agente LLM los interprete después.
// NO se hace normalización ni inferencia aquí.

const input = $("WA Webhook").item.json;

    const platform = 'WhatsApp';
    const text = input.body.data.message.conversation;
    const timestamp = new Date(input.body.data.messageTimestamp * 1000).toISOString();
    const senderId = input.body.data.participantPn || '';
    const messageId = input.body.data.key?.id || '';
    const isBot = false;

  let contact = null;
  const contactMatch = text.match(/(?:PV|privado|mensaje privado|escribirme|llam[ae])\s*[:\-]?\s*(\+?53\s?5\s?\d{7,8}|\d{8})/i);
  if (contactMatch) {
    contact = contactMatch[1].replace(/\D/g, ''); // Normaliza a 56694233
  } else {
    // Buscar número directo en formato cubano
    const phoneMatch = text.match(/(\+53\s?5\s?\d{7,8}|\b5\d{7,8}\b)/);
    if (phoneMatch) {
      contact = phoneMatch[1].replace(/\D/g, '');
    }
  }

  // ─── Construir objeto estandarizado ─────────────────
  return  {
    platform,
    text, // ✅ Texto original intacto
    timestamp,
    contact, // número limpio o null
    sender_id: senderId,
    message_id: messageId,
    is_bot: isBot
  };

// Normaliza una oferta de QvaPay al formato estándar de la tabla `offers`
let offers = [];
const qvapayOffers = $input.first().json.body.data;
for (const raw of qvapayOffers) {

// Determinar tipo (BID/ASK)
const type = raw.type === 'buy' ? 'BID' : 'ASK';

// Normalizar moneda
const currencyMap = {
  'ETECSA': 'SM',
  'CLASICA': 'CLASSIC',
  'BANK_MLC': 'MLC'
};
const baseCurrency = currencyMap[raw.coin] || raw.coin;
const currencyPair = `${baseCurrency}/SQP`;

// Calcular precio (CUP por unidad de activo)
const amount = parseFloat(raw.amount);
const receive = parseFloat(raw.receive);
const price = receive / amount;

// Nivel de riesgo y confianza
const riskLevel = 'bajo';
const riskScore = 0.2;
const sourceTrust = 'alta';

// Contacto (no aplica directamente en QvaPay, pero se puede usar username)
const contactMethods = raw.User.username ? [`@${raw.User.username}`] : [];

// Construir oferta estandarizada
const offer = {
  type,
  currency_pair: currencyPair,
  price: parseFloat(price.toFixed(6)),
  amount: amount,
  trader_name: raw.User.name || "Anónimo",
  username: raw.User.username || "",
  trader_id: raw.User.uuid || null,
  avatar_url: raw.User.image || null,
  deal_count: raw.User._count?.P2P || null,
  acceptance_rate: null, // No disponible en QvaPay
  completion_rate: null,
  avg_payment_time_seconds: null,
  avg_release_time_seconds: null,
  kyc_verified: raw.User.kyc || null,
  vip: raw.User.vip || null,
  phone_verified: raw.User.phone_verified || null,
  telegram_verified: raw.User.telegram_verified || null,
  rating_avg: raw.User.rating_avg || null,
  rating_count: raw.User.rating_count || null,
  risk_level: riskLevel,
  risk_score: riskScore,
  location_province: null,
  location_municipality: null,
  location_neighborhood: null,
  source_trust_level: sourceTrust,
  source_details: {
    original_fragment: raw.message || `Oferta de ${raw.type} de ${raw.coin}`,
    inferred: false,
    inference_rules: null,
    contact_methods: contactMethods,
    payment_methods: null,
    location: null,
    source: {
      platform: "QvaPay",
      source_id: raw.User.uuid,
      post_url: null,
      message_id: raw.uuid,
      sender_username: raw.User.username,
      sender_id: raw.User.uuid
    },
    fraud_tracking: {
      unique_offer_id: `QV_${raw.uuid}`,
      timestamp_iso: raw.created_at,
      reportable: true
    },
    type_name: raw.type // "buy" o "sell"
  },
  created_at: raw.created_at,
  updated_at: raw.created_at
};
  offers.push(offer)
}

return offers;

